-- A database at PRAGMA user_version 14 (busk-stack plan step 14), from before the surface binding
-- grammar (surface-setup plan session 1): every `control_surface_bindings` payload is a `BindingTarget`
-- of the old union, and `uq_surface_binding_slot` has no part. One project, "Surfaces", on the X-Touch
-- Compact: a stack "Act 1" holding cue "Storm" (1), a second stack "Act 2", a loose cue "Chorus", a
-- Look "Haze", a palette "Pink" on a pad of bank "Bank 1" on page "Page 1", and speed master 2
-- "Chase". Its 61 bindings hold every variant once or more: an encoder holding a button target
-- (enc-2 GO, enc-8 a flash at max 200, enc-9 a select), cue and stack rows by int only (btn-2 and
-- enc-7 resolving, btn-4 naming no stack, btn-8 resolving a cue), every on/off form, a row of a type
-- this build never knew (btn-7 on layer B) and two strip rows. Its schema is a step-14 desk's, written
-- by that desk. Frozen: never regenerate it from a later commit.

CREATE TABLE busk_banks (id INTEGER PRIMARY KEY AUTOINCREMENT, column_id INT NOT NULL, sort_order INT NOT NULL, "name" VARCHAR(255) NOT NULL, solo BOOLEAN DEFAULT 0 NOT NULL, flow VARCHAR(16) DEFAULT 'WRAP' NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_banks_column_id__id FOREIGN KEY (column_id) REFERENCES busk_columns(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_banks_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_banks_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_columns (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id INT NOT NULL, "row" INT NOT NULL, sort_order INT NOT NULL, width INT NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_columns_page_id__id FOREIGN KEY (page_id) REFERENCES busk_pages(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_columns_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_row CHECK ("row" BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_width CHECK (width BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_pads (id INTEGER PRIMARY KEY AUTOINCREMENT, bank_id INT NOT NULL, sort_order INT NOT NULL, palette_id INT NULL, look_id INT NULL, cue_id INT NULL, cue_stack_id INT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_pads_bank_id__id FOREIGN KEY (bank_id) REFERENCES busk_banks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_palette_id__id FOREIGN KEY (palette_id) REFERENCES palettes(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_look_id__id FOREIGN KEY (look_id) REFERENCES looks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_cue_id__id FOREIGN KEY (cue_id) REFERENCES cues(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_cue_stack_id__id FOREIGN KEY (cue_stack_id) REFERENCES cue_stacks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_pads_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_pads_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT busk_pad_exactly_one_ref CHECK (((palette_id IS NOT NULL) AND (look_id IS NULL) AND (cue_id IS NULL) AND (cue_stack_id IS NULL)) OR ((palette_id IS NULL) AND (look_id IS NOT NULL) AND (cue_id IS NULL) AND (cue_stack_id IS NULL)) OR ((palette_id IS NULL) AND (look_id IS NULL) AND (cue_id IS NOT NULL) AND (cue_stack_id IS NULL)) OR ((palette_id IS NULL) AND (look_id IS NULL) AND (cue_id IS NULL) AND (cue_stack_id IS NOT NULL))));
CREATE TABLE busk_pages (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INT NOT NULL, "name" VARCHAR(255) NOT NULL, sort_order INT DEFAULT 0 NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_pages_project_id__id FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_pages_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_pages_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
